<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="row"><div class="col-md-12"><h4><?= html_escape($title); ?></h4><form class="form-inline" method="get"><label>From</label> <input class="form-control" type="date" name="from" value="<?= html_escape($from); ?>"> <label>To</label> <input class="form-control" type="date" name="to" value="<?= html_escape($to); ?>"> <button class="btn btn-default">Apply</button> <a class="btn btn-success" href="<?= admin_url('affiliate/analytics_csv?from='.rawurlencode($from).'&to='.rawurlencode($to)); ?>">Export CSV</a></form><div class="panel_s mtop15"><div class="panel-body no-padding"><table class="table"><thead><tr><th>Item</th><th>Name</th><th>Platform</th><th>Date</th><th class="text-right">Clicks</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= (int)$row->item_no; ?></td><td><?= html_escape($row->name); ?></td><td><?= html_escape(ucfirst($row->platform)); ?></td><td><?= html_escape($row->click_date); ?></td><td class="text-right"><strong><?= (int)$row->clicks; ?></strong></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="text-center text-muted">No clicks in this period.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div><?php init_tail(); ?>
